<template>
  <section v-page-loading="{ active: pageLoading, variant: reviewer ? 'list' : 'form', fields: 7 }" class="verification-panel" :class="{ 'reviewer-panel': reviewer }">
    <p class="eyebrow">Business verification</p><h1>{{ reviewer ? 'Supplier Verification' : 'Verify your supplier business' }}</h1>
    <p>Complete business verification to unlock your supplier catalog and clinic orders. Your documents are reviewed by an administrator before any clinic transactions are available.</p>
    <ol v-if="!reviewer" class="onboarding-steps" aria-label="Supplier onboarding steps"><li class="current"><span>1</span><div><strong>Business verification</strong><small>Business details and documents</small></div></li><li :class="{ current: ['Submitted', 'Under review', 'Verified'].includes(application?.verificationStatus) }"><span>2</span><div><strong>Administrator review</strong><small>Document review and decision</small></div></li><li :class="{ current: application?.verificationStatus === 'Verified' }"><span>3</span><div><strong>Supplier portal</strong><small>Catalog and clinic orders</small></div></li></ol>
    <p v-if="error" role="alert" class="error">{{ error }} <button type="button" @click="load">Retry</button></p>
    <template v-if="reviewer">
      <nav class="review-tabs" aria-label="Supplier verification categories">
        <button v-for="tab in reviewTabs" :key="tab.id" type="button" :class="{ active: activeReviewTab === tab.id }" :aria-current="activeReviewTab === tab.id ? 'page' : undefined" @click="activeReviewTab = tab.id">{{ tab.label }} <span>({{ tab.count }})</span></button>
      </nav>
      <p v-if="!filtered.length && !error" class="empty-state">{{ emptyMessage }}</p>
      <article v-for="application in filtered" :key="application.id" class="card">
        <div class="row"><h2>{{ application.businessName || application.companyName || 'Supplier application' }}</h2><div><span class="badge">{{ application.verificationStatus }}</span><span v-if="application.ocrStatus" class="badge">{{ application.ocrStatus }}</span></div></div>
        <p>{{ application.contactEmail || application.email }} · {{ application.contactPhone }}</p><p>{{ application.businessAddress }}</p>
        <p>Registration: {{ application.registrationNumber || 'Not submitted' }} · Tax number: {{ application.taxNumber || 'Not submitted' }}</p><p>Representative: {{ application.representativeName }}</p>
        <div class="documents"><details v-for="(document, kind) in application.documents" :key="kind"><summary>{{ labels[kind] || kind }}: {{ document.name }} · {{ document.ocr?.status || 'OCR unavailable' }}<span v-if="document.ocr?.confidence != null"> · {{ Math.round(document.ocr.confidence * 100) }}%</span></summary><p>{{ document.ocr?.reason || 'No OCR assessment stored.' }}</p><p v-if="document.ocr?.checks?.expiryDate">Expiry: {{ document.ocr.checks.expiryDate }}<span v-if="document.ocr.checks.expiryDaysRemaining != null"> · {{ document.ocr.checks.expiryDaysRemaining }} days remaining</span></p><pre>{{ document.ocr?.extractedText || 'No text was extracted.' }}</pre><button type="button" @click="openDocument(application.id, kind)">Open original document</button></details></div>
        <p v-if="application.revisionReason">Review reason: {{ application.revisionReason }}</p>
        <label v-if="['Submitted', 'Under review', 'Verified'].includes(application.verificationStatus)">Review reason<textarea v-model="reasons[application.id]" rows="2" maxlength="2000" placeholder="Explain requested changes, rejection, or suspension" /></label>
        <div class="actions" v-if="['Submitted', 'Under review'].includes(application.verificationStatus)"><button :disabled="busy" @click="review(application, 'approve')">Approve</button><button :disabled="busy" @click="review(application, 'revise')">Request revisions</button><button :disabled="busy" @click="review(application, 'reject')">Reject</button></div>
        <button v-if="application.verificationStatus === 'Verified'" :disabled="busy" @click="review(application, 'suspend')">Suspend supplier</button>
        <button type="button" @click="loadHistory(application.id)">View review history</button>
        <ol v-if="histories[application.id]"><li v-for="entry in histories[application.id]" :key="entry.id">{{ entry.previousStatus }} → {{ entry.nextStatus }} · {{ entry.reason || entry.action }} · {{ entry.actorId }}</li></ol>
      </article>
    </template>
    <template v-else-if="application">
      <div class="card"><span class="badge">{{ application.verificationStatus }}</span><span v-if="application.ocrStatus" class="badge">{{ application.ocrStatus }}</span><p v-if="application.revisionReason">{{ application.revisionReason }}</p><p v-if="application.verificationStatus === 'Verified'">Your supplier business is verified. Catalog and clinic order features are unlocked.</p><p v-else-if="['Submitted', 'Under review'].includes(application.verificationStatus)">Your documents are awaiting review. The supplier portal remains locked until approval. You can return here to see the decision.</p><p v-else-if="application.verificationStatus === 'Rejected'">Your application was rejected. Contact the administrator for more information or submit corrected details if resubmission is allowed.</p><RouterLink v-if="application.verificationStatus === 'Verified'" class="portal-link" to="/supplier/supplies">Continue to supplier portal</RouterLink></div>
      <form @submit.prevent="submit" class="card">
        <fieldset :disabled="locked || busy"><div class="fields"><label v-for="field in fields" :key="field.key">{{ field.label }}<input v-model.trim="form[field.key]" :type="field.type || 'text'" required maxlength="500" /></label></div>
          <div class="ocr-workspace"><div class="documents"><label v-for="kind in Object.keys(labels)" :key="kind" @click="selectedDocumentKind = kind"><span>{{ labels[kind] }} {{ kind === 'distribution' ? '(optional)' : '(required)' }}</span><input type="file" accept="application/pdf,image/png,image/jpeg" @change="upload(kind, $event)" /><small>{{ application.documents?.[kind]?.name || 'PDF, PNG, or JPEG · up to 10 MB' }}</small><small v-if="application.documents?.[kind]?.ocr" class="ocr-status">{{ application.documents[kind].ocr.status }} · {{ application.documents[kind].ocr.reason }}</small></label></div><aside class="ocr-reader" aria-live="polite"><div class="reader-heading"><div><p class="eyebrow">Document reader</p><h2>{{ labels[selectedDocumentKind] || 'Select a document' }}</h2></div><button v-if="application.documents?.[selectedDocumentKind]" type="button" @click="openDocument(application.id, selectedDocumentKind)">Open file</button></div><template v-if="selectedDocument?.ocr"><div class="ocr-summary"><span class="badge">{{ selectedDocument.ocr.status }}</span><strong>{{ Math.round(Number(selectedDocument.ocr.confidence || 0) * 100) }}%</strong></div><p>{{ selectedDocument.ocr.reason }}</p><p v-if="selectedDocument.ocr.checks?.businessNameMatch !== null">Business name: {{ selectedDocument.ocr.checks.businessNameMatch ? 'Matched' : 'Not matched' }}</p><p v-if="selectedDocument.ocr.checks?.expiryDate">Expiry: {{ selectedDocument.ocr.checks.expiryDate }}<span v-if="selectedDocument.ocr.checks.expiryDaysRemaining !== null"> · {{ selectedDocument.ocr.checks.expiryDaysRemaining }} days remaining</span></p><pre class="extracted-text">{{ selectedDocument.ocr.extractedText || 'No text was extracted.' }}</pre></template><p v-else class="reader-empty">Upload a document to see its extracted text and validation results here.</p></aside></div>
          <button type="submit" :disabled="busy">{{ busy ? 'Saving…' : 'Submit for verification' }}</button>
        </fieldset>
      </form>
    </template>
    <a v-if="documentUrl" class="document-link" :href="documentUrl" target="_blank" rel="noopener">Open selected document (link expires in 5 minutes)</a>
  </section>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import { auth } from '@/config/firebaseConfig'
import { OTP_API_BASE } from '@/utils/runtimeConfig'
import { usePageLoading } from '@/composables/usePageLoading'
import { toast } from 'vue3-toastify'
const props = defineProps({ reviewer: Boolean })
const { pageLoading, trackPageLoad } = usePageLoading()
const application = ref(null), applications = ref([]), form = ref({}), activeReviewTab = ref('ocr'), reasons = ref({}), histories = ref({}), error = ref(''), busy = ref(false), documentUrl = ref(''), selectedDocumentKind = ref('registration')
const selectedDocument = computed(() => application.value?.documents?.[selectedDocumentKind.value] || null)
const labels = { registration: 'Business registration', permit: 'Business permit / tax document', representative: 'Representative authorization', distribution: 'Distribution credentials' }
const fields = [{ key: 'businessName', label: 'Legal business name' }, { key: 'registrationNumber', label: 'Registration number' }, { key: 'taxNumber', label: 'Tax number' }, { key: 'businessAddress', label: 'Business address' }, { key: 'representativeName', label: 'Authorized representative' }, { key: 'contactEmail', label: 'Contact email', type: 'email' }, { key: 'contactPhone', label: 'Contact phone', type: 'tel' }]
const locked = computed(() => ['Submitted', 'Under review', 'Verified', 'Suspended'].includes(application.value?.verificationStatus))
const getReviewCategory = a => {
  const status = String(a.verificationStatus || '').toLowerCase()
  if (status === 'verified') return 'approved'
  if (status === 'rejected') return 'rejected'
  if (!['submitted', 'under review'].includes(status)) return 'other'
  return String(a.ocrStatus || '').toLowerCase() === 'ocr verified' ? 'ocr' : 'manual'
}
const reviewTabs = computed(() => [
  { id: 'ocr', label: 'OCR-Verified', count: applications.value.filter(a => getReviewCategory(a) === 'ocr').length },
  { id: 'manual', label: 'Manual review', count: applications.value.filter(a => getReviewCategory(a) === 'manual').length },
  { id: 'rejected', label: 'Rejected', count: applications.value.filter(a => getReviewCategory(a) === 'rejected').length },
  { id: 'approved', label: 'Approved', count: applications.value.filter(a => getReviewCategory(a) === 'approved').length },
])
const filtered = computed(() => applications.value.filter(a => getReviewCategory(a) === activeReviewTab.value))
const emptyMessage = computed(() => ({ ocr: 'No OCR-verified supplier applications are awaiting approval.', manual: 'No supplier applications need manual review.', rejected: 'No rejected supplier applications.', approved: 'No approved suppliers yet.' })[activeReviewTab.value])
const api = async (path, body) => { const token = await auth.currentUser.getIdToken(); const response = await fetch(OTP_API_BASE + path, { method: body ? 'POST' : 'GET', headers: { Authorization: `Bearer ${token}`, 'content-type': 'application/json' }, body: body ? JSON.stringify(body) : undefined }); const result = await response.json(); if (!response.ok || !result.success) throw new Error(result.error || 'Unable to complete request.'); return result.data }
const load = trackPageLoad(async () => { error.value = ''; try { if (props.reviewer) applications.value = await api('/admin/supplier-verification'); else { application.value = await api('/supplier-verification/me'); form.value = Object.fromEntries(fields.map(field => [field.key, application.value[field.key] || (field.key === 'contactEmail' ? auth.currentUser.email : '')])) } } catch (e) { error.value = e.message } })
const upload = async (kind, event) => { const file = event.target.files?.[0]; if (!file) return; selectedDocumentKind.value = kind; if (file.size > 10 * 1024 * 1024) { toast.error('Choose a file up to 10 MB.'); return } busy.value = true; try { const base64 = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(',')[1]); reader.onerror = reject; reader.readAsDataURL(file) }); const document = await api('/supplier-verification/documents', { kind, name: file.name, base64, businessName: form.value.businessName, representativeName: form.value.representativeName }); application.value.documents = { ...application.value.documents, [kind]: document }; toast.success(document.ocr?.status === 'verified' ? 'Document uploaded and OCR checks passed.' : 'Document uploaded. Review the OCR result before submitting.') } catch (e) { toast.error(e.message) } finally { busy.value = false; event.target.value = '' } }
const submit = async () => { busy.value = true; try { await api('/supplier-verification/submit', form.value); await load(); toast.success('Application submitted for review.') } catch (e) { error.value = e.message } finally { busy.value = false } }
const review = async (a, action) => { busy.value = true; try { await api(`/admin/supplier-verification/${encodeURIComponent(a.id)}/review`, { action, reason: reasons.value[a.id] || '' }); await load(); if (histories.value[a.id]) await loadHistory(a.id); toast.success('Review decision saved.') } catch (e) { toast.error(e.message) } finally { busy.value = false } }
const openDocument = async (id, kind) => { try { documentUrl.value = (await api(`/supplier-verification/${encodeURIComponent(id)}/documents/${encodeURIComponent(kind)}`)).url } catch (e) { toast.error(e.message) } }
const loadHistory = async id => { try { histories.value[id] = await api(`/admin/supplier-verification/${encodeURIComponent(id)}/history`) } catch (e) { toast.error(e.message) } }
onMounted(load)
</script>
<style scoped>
.verification-panel{max-width:960px;margin:auto;color:#3d281d}.eyebrow{font-size:.7rem;text-transform:uppercase;letter-spacing:.18em;color:#8d5a3b}h1{font:700 2rem Georgia,serif;margin:.5rem 0}h2{font:700 1.2rem Georgia,serif}p{margin:.6rem 0;line-height:1.6}.card{padding:1.4rem;margin-top:1.3rem;border:1px solid #e0c09a;border-radius:1.2rem;background:#fffaf3}.row,.actions{display:flex;gap:.75rem;justify-content:space-between;flex-wrap:wrap}.badge{background:#f7ead7;padding:.3rem .7rem;border-radius:1rem;font-size:.8rem}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}label{display:block;font-size:.85rem;margin:.75rem 0}input,select,textarea{display:block;width:100%;border:1px solid #d9be9b;border-radius:.65rem;padding:.65rem;background:#fff;color:#3d281d;margin-top:.4rem}button{border:1px solid #d9be9b;border-radius:.7rem;padding:.55rem .85rem;background:#f7ead7;color:#6f4a2d;margin:.3rem 0}button[type=submit]{background:#8d5a3b;color:#fff}.error{color:#a22a26;background:#fff0ed;padding:1rem;border-radius:.75rem}small{color:#775743}.document-link{display:block;margin:1rem 0;text-decoration:underline}fieldset{min-width:0;border:0;padding:0}button:disabled,fieldset:disabled{opacity:.6}.filter{max-width:300px}.onboarding-steps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.75rem;padding:0;margin:1.5rem 0;list-style:none}.onboarding-steps li{display:flex;align-items:center;gap:.7rem;padding:.8rem;border:1px solid #e0c09a;border-radius:.9rem;background:#fffaf3;color:#8a7567}.onboarding-steps li.current{border-color:#a8714d;background:#f7ead7;color:#573923}.onboarding-steps li>span{display:grid;place-items:center;flex:0 0 2rem;height:2rem;border-radius:50%;background:#ead3b8;font-weight:700}.onboarding-steps strong,.onboarding-steps small{display:block}.onboarding-steps strong{font-size:.8rem}.onboarding-steps small{font-size:.68rem}.portal-link{display:inline-block;margin-top:.5rem;color:#8d5a3b;font-weight:700;text-decoration:underline}.ocr-workspace{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:1.25rem;margin-top:1.25rem}.ocr-reader{position:sticky;top:1rem;align-self:start;min-width:0;max-height:42rem;overflow:auto;padding:1rem;border:1px solid #d9be9b;border-radius:1rem;background:#fff;color:#3d281d}.reader-heading,.ocr-summary{display:flex;justify-content:space-between;align-items:center;gap:.75rem}.reader-heading h2{margin:.25rem 0}.ocr-summary{margin:.8rem 0}.extracted-text,.documents pre{max-height:20rem;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;padding:.85rem;border-radius:.7rem;background:#f8f0e5;color:#493426;font: .78rem/1.5 ui-monospace,monospace}.reader-empty{padding:2rem 0;color:#775743}.ocr-status{display:block;margin-top:.45rem;color:#65452f;line-height:1.4}.documents details{margin:.6rem 0;padding:.7rem;border:1px solid #ead6b8;border-radius:.7rem;background:#fffaf3}.documents summary{cursor:pointer;font-size:.83rem;font-weight:600}.documents details p{font-size:.8rem}.documents details pre{max-height:12rem}.ocr-workspace label{padding:.75rem;border:1px solid #e0c09a;border-radius:.8rem;background:#fffaf3}.ocr-workspace label:focus-within{outline:2px solid #a8714d}.ocr-workspace .documents{display:flex;flex-direction:column;gap:.6rem}.ocr-workspace .documents label{margin:0}@media(max-width:760px){.ocr-workspace{grid-template-columns:1fr}.ocr-reader{position:static;max-height:28rem}}@media(max-width:640px){.fields{grid-template-columns:1fr}.onboarding-steps{grid-template-columns:1fr}.onboarding-steps li{padding:.65rem}h1{font-size:1.5rem}.card{padding:1rem}}
.review-tabs{display:flex;max-width:100%;gap:.5rem;overflow-x:auto;border:1px solid #334155;border-radius:.8rem;background:#1e293b;padding:.5rem;margin:1.25rem 0}.review-tabs button{flex:0 0 auto;margin:0;border:0;background:transparent;color:#cbd5e1}.review-tabs button.active{background:#0f766e;color:#fff}.review-tabs button span{font-size:.75rem;opacity:.8}.empty-state{padding:1.5rem;border:1px dashed #475569;border-radius:.8rem;color:#94a3b8;text-align:center}.reviewer-panel{max-width:none;color:#f1f5f9}.reviewer-panel .eyebrow{color:#94a3b8}.reviewer-panel h1,.reviewer-panel h2{color:#f8fafc}.reviewer-panel>p{color:#94a3b8}.reviewer-panel .card{border-color:#334155;background:#1e293b;color:#e2e8f0;border-radius:.8rem}.reviewer-panel .badge{background:#334155;color:#e2e8f0}.reviewer-panel .documents details{border-color:#475569;background:#0f172a}.reviewer-panel .documents summary,.reviewer-panel .documents details p{color:#e2e8f0}.reviewer-panel .documents pre{background:#0b1220;color:#cbd5e1}.reviewer-panel button{border-color:#475569;background:#334155;color:#f1f5f9}.reviewer-panel .actions button:first-child{background:#059669;border-color:#059669}.reviewer-panel .actions button:last-child{background:#be123c;border-color:#be123c}.reviewer-panel textarea{background:#0f172a;color:#f8fafc;border-color:#475569}.reviewer-panel .error{color:#fecdd3;background:#4c0519}.reviewer-panel .document-link{color:#7dd3fc}
</style>
